INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65229768', 65229768, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR PENYUSUNAN DOKUMEN ANALISIS KELEMBAGAAN LINGKUP PERUMAHAN, AIR MINUM, AIR LIMBAH DOMESTIK DAN PERSAMPAHAN KEGIATAN PENYUSUNAN POLICY BRIEF STRATEGIS TRANSFORMASI TATA KELOLA LINGKUP PERUMAHAN, AIR MINUM, AIR LIMBAH DOMESTIK, DAN PERSAMPAHAN', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', 'Mengumpulkan dan mengolah data serta identifikasi awal terhadap kondisi tata kelola dan kebijakan strategis pada sektor perumahan, air minum, air limbah domestik, dan persampahan sebagai dasar analisis kelembagaan; Menyusun kerangka strategi dan rencana aksi penguatan kelembagaan yang selaras dengan arah perencanaan awal, mencakup penguatan tata kelola, keterpaduan lintas sektor, integrasi perencanaan pusat–daerah, serta peningkatan kapasitas dan kolaborasi pemangku kepentingan, dalam bentuk rumusan konseptual dan analitis; Menyusun rancangan konseptual kegiatan uji coba (piloting) penguatan kelembagaan dan sinergi program di kota/kabupaten terpilih sebagai bahan pembelajaran kebijakan terkait penerapan pendekatan tata kelola transformatif; Menyusun bahan substansi dan kerangka pembahasan untuk forum diskusi dan pertukaran pandangan lintas pemangku kepentingan, sebagai bagian dari proses pengujian dan penajaman analisis serta strategi penguatan kelembagaan; Menyusun ringkasan hasil pembahasan lintas pemangku kepentingan dalam bentuk bahan analisis dan rekomendasi kebijakan yang relevan dengan ruang lingkup Penyusunan Policy Brief Strategis Transformasi Tata Kelola; Menyusun bahan analitis tambahan yang relevan dengan kebutuhan penguatan tata kelola dan kelembagaan sektor perumahan dan infrastruktur permukiman, sepanjang masih berada dalam kerangka kegiatan dan capaian output yang ditetapkan.', 'Pendidikan minimal S1 semua jurusan (dibuktikan dengan ijazah); Diutamakan Tenaga ahli dalam negeri (dibuktikan dengan kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir terkait perencanaan pembangunan nasional (dibuktikan dengan kontrak); Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan) dalam lingkup air minum/sanitasi/persampahan/perumahan merupakan dalam kurun waktu 4 (empat) tahun; Memiliki pengalaman kerja dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai total HPS/Pagu Anggaran; Memiliki kemampuan dalam menyusun laporan, kajian, maupun dokumen secara sistematis. Bersedia tidak memperoleh hal-hal sebagai berikut: Barang Milik Negara; THR dan Gaji 13; BPJS (Kesehatan dan Ketenagakerjaan); Fasilitas klinik kecuali dalam kondisi darurat; dan Tidak Menuntut diangkat menjadi ASN.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2010161);
