INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65228034', 65228034, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR PENYUSUNAN DOKUMEN ANALISIS PERMUKIMAN KUMUH TERPADU  KEGIATAN KOORDINASI PROGRAM TIGA JUTA RUMUAH TAHUN', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 86713200, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', 'Melakukan telaah serta merumuskan rekomendasi strategi penanganan permukiman kumuh dalam kerangka Program Tiga Juta Rumah; Melaksanakan kegiatan pengumpulan data terkait program penanganan permukiman kumuh terpadu; Memfasilitasi pemerintah daerah dalam pelaksanaan program permukiman kumuh terpadu dan pendalaman isu teknis di tingkat daerah; Mengelola proses diskusi teknis, workshop, FGD, atau kegiatan lapangan guna mendukung pengumpulan informasi dan pe\\nyusunan opsi solusi; Memberikan masukan substansi berbasis analisis terkait isu permukiman kumuh; dan Melaksanakan tugas lainnya sesuai arahan Direktur Perumahan dan Infrastruktur Kawasan Permukiman, Kementerian PPN/Bappenas RI.', 'Pendidikan S1 dari jurusan perencanaan wilayah dan kota, studi pembangunan (dibuktikan dengan ijazah); Diutamakan Tenaga ahli dalam negeri (dibuktikan dengan kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta (dibuktikan dengan kontrak); Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi atau karakteristik lainnya yang bisa menggambarkan kesamaan) mengenai konsep permukiman kumuh dalam kurun waktu 3 (tiga) tahun; Memiliki pengalaman kerja dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai total HPS/Pagu Anggaran; Memiliki kemampuan dalam menyusun laporan maupun dokumen secara sistematis; Memiliki pemahaman dasar mengenai konsep permukiman kumuh, indikator kumuh, serta pendekatan penanganan terpadu; Bersedia tidak memperoleh hal-hal sebagai berikut : Barang Milik Negara; THR dan Gaji 13; BPJS (Kesehatan dan Ketenagakerjaan) Fasilitas klinik kecuali dalam kondisi darurat; dan Tidak Menuntut diangkat Menjadi ASN', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2010251);
