INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65228421', 65228421, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR PENYUSUNAN DATA ANALISIS PERSAMPAHAN  KEGIATAN KOORDINASI REFORMASI PENGELOLAAN PERSAMPAHAN TERINTEGRASI DARI HULU KE HILIR', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 91850000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', 'Mengidentifikasi ketersediaan data persampahan eksisting di nasional dan daerah serta kelengkapannya; Mengumpulkan data-data pengelolaan sampah dari luar Indonesia baik berupa data baku, data olahan, ataupun praktik baik, pembelajaran, dan data lainnya; Mengumpulkan berita terkait persampahan dari berbagai media sebagai data kualitatif indikasi kondisi persampahan dari persepsi publik; Melakukan pengolahan data dan berita yang didapatkan baik di tingkat nasional maupun global sebagai pengelolaan pengetahuan untuk pengembangan kebijakan nasional; dan Melakukan penyampaian berita dan penyajian data dalam peningkatan pengelolaan pengetahuan untuk pengembangan kebijakan nasional.', 'Pendidikan minimal S1 bidang perencanaan (planologi / perencanaan wilayah / kebijakan publik / sebidang) atau lingkungan (teknik lingkungan / infrastruktur lingkungan / rekayasa lingkungan / ilmu lingkungan); Diutamakan Tenaga ahli dalam negeri (dibuktikan dengan kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir terkait perencanaan pembangunan nasional (dibuktikan dengan kontrak); Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan) dalam melakukan pengolah data persampahan merupakan dalam kurun waktu 4 (empat) tahun; Memiliki pengalaman kerja dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai total HPS/Pagu Anggaran; Memiliki pengalaman kerja minimal 2 (dua) tahun dengan stakeholder pembangunan (pemerintah dan non-pemerintah) di sektor persampahan; Memiliki kemampuan dalam menyusun laporan, kajian, maupun dokumen secara sistematis; dan Bersedia tidak memperoleh hal-hal sebagai berikut : Barang Milik Negara; THR dan Gaji 13; BPJS (Kesehatan dan Ketenagakerjaan) Fasilitas klinik kecuali dalam kondisi darurat; dan Tidak Menuntut diangkat Menjadi ASN', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2011764);
