INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65232620', 65232620, 'analyze_legacy', 'Pusat Pelaporan Dan Analisis Transaksi Keuangan', 'central', 'Pendidikan dan Pelatihan Anti Pencucian Uang PPATK', 'Pengadaan Pemeliharaan Rutin Chiller pada Pusdiklat APUPPT Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Depok (Kota)', 104784000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 0, 0, '( 2, Unit, @ 52392000)', 'Pengadaan Pemeliharaan Rutin Chiller pada Pusdiklat APUPPT Tahun Anggaran 2026', 'Pemeliharaan rutin dilaksanakan terhadap perangkat chiller eksisting, Daikin Watercooled Chiller model UAA100 1FST4 sebanyak 2 (dua) unit. Pemeliharaan dilakukan terhadap unit chiller tanpa penggantian unit utama, kecuali ditentukan lain berdasarkan hasil pemeriksaan teknis. b. Spesifikasi Kinerja Setelah dilakukan pekerjaan pemeliharaan rutin, perangkat chiller harus memenuhi kriteria mutu dan kinerja sebagai berikut: 1) Kondisi Operasional a) Seluruh unit chiller berada dalam kondisi bersih, layak operasi, dan berfungsi normal sesuai standar pabrikan; b) Chiller mampu beroperasi secara stabil dalam menghasilkan air dingin (chilled water) yang selanjutnya didistribusikan ke sistem tata udara gedung untuk menghasilkan udara dingin di seluruh area gedung. 2) Kinerja Sistem Pendinginan a) Suhu air keluar (leaving chilled water temperature) berada dalam rentang kerja normal sesuai desain sistem dan spesifikasi pabrikan; b) Tidak terdapat gangguan signifikan pada tekanan, aliran, maupun siklus pendinginan selama unit beroperasi. 3) Komponen Sensor dan Panel Kontrol a) Seluruh sensor, panel kontrol, dan sistem proteksi pada perangkat chiller berada dalam kondisi baik, tidak mengalami kerusakan, dan berfungsi sesuai peruntukannya; b) Sistem kontrol mampu menampilkan parameter operasi dengan akurat serta memberikan peringatan apabila terjadi kondisi tidak normal. 4) Keandalan dan Keamanan Operasi a) Chiller dapat dioperasikan secara aman tanpa menimbulkan getaran berlebih, suara abnormal, atau indikasi kebocoran pada sistem; b) Seluruh pengamanan dasar (safety device) berfungsi dengan baik sesuai standar operasional. c. Standar Mutu Pelaksanaan Pekerjaan pemeliharaan harus dilaksanakan dengan mengacu pada: 1) Manual operasi dan pemeliharaan dari pabrikan Daikin; 2) Standar praktik pemeliharaan sistem tata udara (HVAC) yang berlaku; 3) Ketentuan keselamatan dan kesehatan kerja (K3) di lingkungan gedung Pusdiklat APUPPT. Hasil akhir pemeliharaan harus dapat dibuktikan melalui pengujiang fungsi (test run) dan pencatatan parameter operasi, serta dilaporkan secara tertulis kepada Pejabat Pembuat Komitmen (PPK). Chiller Model UAA100 1FST4 (2 Unit): • Menganalisa operasional data unit yang sudah diambil; • Memeriksa kondisi yang tidak normal; • Memeriksa kondisi oli compressor; • Memeriksa Pressure drop Oil filter; • Memeriksa Heater oli; • Memeriksa beban compressor (operasional load dan unload); • Memeriksa Valve expansi; • Memeriksa Pressure drop Air Chiller (Chilled water); • Memeriksa settingan dan pengoperasian compressor, temperature, tekanan, overloadtrip & parameter lain; • Memeriksa tekanan discharge dan suction; • Memeriksa temperature discharge dan suction; • Memeriksa kontaktor dan komponen elektrikal; • Membersihkan contact point contactor; • Memeriksa tegangan listrik (toleransi + 10%) • Memeriksa koneksi kabel; • Mengisi Log sheet setelah di Service; • Pembersihan Fin koil kondensor; • Menguji kebocoran zat pendingin; • Cleaning area setelah pembersihan condenser; • Mengevaluasi kondisi operasional unit chiller dan memberikan laporan; Berdiskusi dengan tim teknik owner dan memberikan rekomendasi jika ada yang harus dilakukan penggantian sparepart No Perangkat Chiller Qty Kunjungan Keterangan 1 Chiller 1 4 kunjungan Januari, April, Agustus, November 2026 2 Chiller 2 4 kunjungan Januari, April, Agustus, November 2026 a. Tenaga Teknis : Minimum 1 personel dengan sertifikat terkait perangkat Chiller Daikin b. Peralatan : Tang Ampere, manifold, tespen, tang kombinasi, obeng, vacuum pump, dan lain-lain.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2013357);
