INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65233413', 65233413, 'analyze_legacy', 'Lembaga Kebijakan Pengadaan Barang/Jasa Pemerintah', 'central', 'LEMBAGA KEBIJAKAN PENGADAAN BARANG/JASA PEMERINTAH', 'Jasa Lainnya Pendukung Operasional Kegiatan untuk UKM', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 84000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 OB', 'membantu penyusunan rancangan strategi kegiatan PKP mulai dari proses perencanaan, implementasi, dan monitoring; Menyusun KAK dan RAB kegiatan PKP serta dokumen pendukung lainnya; mengelola database penyedia peserta PKP dalam aplikasi BISA Pengadaan, guna mengetahui jumlah penyedia yang terdaftar setiap bulannya; mempelajari kegiatan yang dilaksanakan oleh Direktorat Pengembangan Iklim Usaha dan Kerjasama Internasional; dan membantu melaksanakan kegiatan lainnya sesuai dengan perintah (disposisi) dari atasan di Direktorat Pengembangan Iklim Usaha dan Kerjasama Internasional', '1. Minimal berpendidikan S-1/D-IV untuk semua jurusan, lebih diutamakan jurusan Ekonomi/Manajemen/Teknik Informatika/Sistem Informasi/Ilmu Komputer/Manajemen Informatika/Teknologi Informasi. 2. Memiliki nilai indeks prestasi kumulatif (IPK) minimal 3.00 dari skala 4.00. 3. Minimal memiliki 1 (satu) tahun pengalaman pada projek pengembangan UMKM. 4. Memiliki kemampuan komunikasi yang baik untuk melakukan sinergi dan koordinasi antar stakeholder (pemerintah, swasta, dunia usaha, dan masyarakat). 5. Mampu menuangkan rancangan konsep dalam sebuah laporan dan mempresentasikannya dengan baik. 6. Memahami pengoperasian Microsoft Office terutama Microsoft Excel dan Powerpoint. 7. Memiliki pengalaman di bidang pengembangan dan pengelolaan website/situs dan data base. 8. Diutamakan memiliki jaringan yang luas dengan media elektronik. 9. Mampu bekerja mandiri maupun dalam tim.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2014765);
