INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65236045', 65236045, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan pada Penyusunan Dokumen Model Pendekatan Keterkaitan Pembiayaan dan Investasi Terhadap Prioritas Nasional 2 yang Mendukung Pencapaian Rencana Pembangunan Jangka Menengah 2025-2029;', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 165600000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Kebijakan dan Regulasi Pembangunan Ruang lingkup kajian meliputi kebijakan fiskal, dukungan pembiayaan dan investasi, serta regulasi yang relevan dapat mendukung ketercapaian Prioritas Nasional 2. Indikator Pembangunan Prioritas Nasional 2 dan Kerangka Metodologis Ruang lingkup mencakup indikator - indikator pembangunan Prioritas Nasional 2 sebagaimana tercantum dalam RPJMN 2025 – 2029, termasuk kerangka teori, pendekatan metodologi pengukuran, serta keterkaitannya dengan pembiayaan dan investasi pembangunan; Inventarisasi Program dan Keluaran Pembangunan Ruang lingkup mencakup pemetaan Program Prioritas (PP), Kegiatan Prioritas (KP), Proyek Prioritas (Pro-P), Klasifikasi Rincian Output (KRO), dan Rincian Output (RO) yang didukung oleh pembiayaan dan investasi pada sektor Prioritas Nasional 2; Model Pendekatan Pembiayaan dan Investasi', 'Diutamakan Konsultan dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); Memiliki Pendidikan S2 di bidang Keuangan (dibuktikan dengan ijazah jenjang Pendidikan); Memiliki kemampuan yang baik dan berpengalaman dalam menulis dan menyusun dokumen strategis yang berhubungan dengan kegiatan Pembiayaan dan Investasi pembangunan Sektor Terkait PN 2 seperti Pinjaman Luar Negeri dan Pinjaman Dalam Negeri Khusus; Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak (dibuktikan dengan surat referensi/kontrak kerja); Memiliki pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS atau Pagu Anggaran (dibuktikan dengan surat referensi/kontrak kerja) menjadi nilai tambah;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2017452);
