INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65232432', 65232432, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Dokumen Model Pendekatan Keterkaitan Pembiayaan dan Investasi terhadap Prioritas Nasional 5 yang Mendukung Pencapaian Rencana Pembangunan Jangka Menengah 2025-2029', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 94800000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Kebijakan dan Regulasi Pembangunan Ruang lingkup kajian meliputi kebijakan fiskal, dukungan pembiayaan dan investasi, serta regulasi yang relevan dapat mendukung ketercapaian Prioritas Nasional 5. Indikator Pembangunan Prioritas Nasional 5 dan kerangka Metodologis Ruang lingkup mencakup indikator - indikator pembangunan Prioritas Nasional 5 sebagaimana tercantum dalam RPJMN 2025 – 2029, termasuk kerangka teori, pendekatan metodologi pengukuran, serta keterkaitannya dengan pembiayaan dan investasi pembangunan. Inventarisasi Program dan Keluaran Pembangunan Ruang lingkup mencakup pemetaan Program Prioritas (PP), Kegiatan Prioritas (KP), Proyek Prioritas (Pro-P), Klasifikasi Rincian Output (KRO), dan Rincian Output (RO) yang didukung oleh pembiayaan dan investasi pada sektor Prioritas Nasional', 'Kebijakan dan Regulasi Pembangunan Ruang lingkup kajian meliputi kebijakan fiskal, dukungan pembiayaan dan investasi, serta regulasi yang relevan dapat mendukung ketercapaian Prioritas Nasional 5. Indikator Pembangunan Prioritas Nasional 5 dan kerangka Metodologis Ruang lingkup mencakup indikator - indikator pembangunan Prioritas Nasional 5 sebagaimana tercantum dalam RPJMN 2025 – 2029, termasuk kerangka teori, pendekatan metodologi pengukuran, serta keterkaitannya dengan pembiayaan dan investasi pembangunan. Inventarisasi Program dan Keluaran Pembangunan Ruang lingkup mencakup pemetaan Program Prioritas (PP), Kegiatan Prioritas (KP), Proyek Prioritas (Pro-P), Klasifikasi Rincian Output (KRO), dan Rincian Output (RO) yang didukung oleh pembiayaan dan investasi pada sektor Prioritas Nasional 5. Model Pendekatan Pembiayaan dan Investasi Ruang lingkup mencakup pengembangan kerangka model pendekatan yang menjelaskan keterkaitan antara pembiayaan, investasi, kapasitas fiskal, dan capaian Prioritas Nasional 5 dengan opsi model kuantitatif/kualitatif/hybrid. Kesenjangan Pembiayaan dan Investasi Ruang lingkup mencakup identifikasi dan analisis kesenjangan (gap analysis) antara kebutuhan pembiayaan dan investasi untuk mendukung pencapaian indikator Prioritas Nasional 5. Rekomendasi Strategis Kebijakan Ruang lingkup mencakup perumusan arah dan opsi strategis kebijakan pembiayaan dan investasi untuk mendukung pencapaian indikator Prioritas Nasional 5. Penyusunan Dokumen dan Bahan Pendukung Ruang lingkup mencakup penyusunan dokumen kajian, laporan berkala, bahan presentasi, dan dokumen pendukung lainnya yang diperlukan dalam rangka pelaksanaan kegiatan sesuai arahan pimpinan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2018737);
