INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65275238', 65275238, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'UNIT PENYELENGGARA BANDAR UDARA RAHADI OESMAN DI KETAPANG', 'Belanja Pemeliharaan Jalan dan Jembatan (Runway) 14850 M2', 'Pekerjaan Konstruksi', 'Penunjukan Langsung', 'Kalimantan Barat, Ketapang (Kab.)', 252450000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '14850 m2', 'Belanja pemeliharaan jalan dan jembatan (runway) berupa kegiatan perawatan rutin dan berkala untuk menjaga kondisi permukaan landasan tetap laik operasi dan memenuhi standar keselamatan penerbangan, meliputi pembersihan FOD, penambalan retak/lubang (patching), perbaikan sambungan (joint sealant), pelapisan ulang/marking, perbaikan bahu dan drainase, perawatan struktur pendukung, serta pekerjaan lain yang diperlukan guna mempertahankan fungsi, kekuatan, dan umur layanan runway sesuai ketentuan teknis kebandarudaraan.', 'Pekerjaan meliputi pemeliharaan rutin dan berkala runway beserta struktur pendukung untuk menjaga keselamatan dan kelaikan operasi penerbangan, berupa pembersihan permukaan dari FOD dan genangan, perawatan bahu dan drainase, penambalan lubang (patching), perbaikan retak dan sambungan (crack/joint sealing), perbaikan deformasi perkerasan, pelapisan/overlay tipis bila diperlukan, pengecatan ulang marka runway, serta perbaikan minor struktur beton/jembatan dan perlengkapan keselamatan. Material yang digunakan harus memenuhi standar teknis kebandarudaraan (ICAO/Dirjen Perhubungan Udara) dan spesifikasi umum perkerasan jalan. Pelaksanaan pekerjaan dilakukan dengan metode aman, bertahap, tidak